<?php use App\Helpers\ViewHelper; ?>
<div class="container page-head"><?php require dirname(__DIR__) . '/partials/breadcrumbs.php'; ?><p class="eyebrow">Tài khoản</p><h1>Lịch sử đơn hàng</h1></div>
<section class="container section">
<?php if (empty($orders)): ?><div class="empty-state"><h2>Chưa có đơn hàng</h2><p>Đơn hàng của bạn sẽ xuất hiện ở đây.</p></div><?php else: ?><div class="table-wrap"><table class="admin-table order-history-table"><thead><tr><th>Mã đơn</th><th>Sản phẩm đã mua</th><th>Ngày đặt</th><th>Tổng tiền</th><th>Trạng thái</th><th></th></tr></thead><tbody><?php foreach ($orders as $order): ?><tr><td><?= ViewHelper::escape($order['order_code']) ?></td><td><ul class="order-products"><?php foreach (($orderItems[(int)$order['id']] ?? []) as $item): ?><li><span><?= ViewHelper::escape($item['book_title']) ?> × <?= (int)$item['quantity'] ?></span><?php if ($order['status'] === 'completed' && !empty($item['book_slug'])): ?><?php if (!empty($item['review_id'])): ?><span class="review-done">Đã đánh giá</span><?php else: ?><a class="action-button review-link" href="/books/<?= ViewHelper::escape(rawurlencode((string)$item['book_slug'])) ?>#reviews">Đánh giá</a><?php endif; ?><?php endif; ?></li><?php endforeach; ?></ul></td><td><?= ViewHelper::escape($order['created_at']) ?></td><td><?= ViewHelper::money((int)$order['total']) ?></td><td><?= ViewHelper::escape(ViewHelper::orderStatus((string)$order['status'])) ?></td><td><a class="action-button" href="/orders/<?= (int)$order['id'] ?>">Chi tiết</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
